sheet.css:
.pk{--paper:#fff;--ink:#000;--grey:#6e6e6e;--red:#e2231a;
  background:var(--paper);color:var(--ink);
  font-family:Helvetica,'Helvetica Neue',Arial,sans-serif;font-weight:400}
[data-theme=dark].pk,[data-theme=dark] .pk{--paper:#000;--ink:#fff;--grey:#a0a0a0}
.stage.pk{--page:var(--paper);background:var(--paper)}
.pk h3,.pk h4{font-weight:700;letter-spacing:-.03em;line-height:.92;margin:0}
.pk p{margin:0;letter-spacing:.02em;line-height:1.35}
.meta{font-size:11px;letter-spacing:.02em;color:var(--grey);text-transform:uppercase}
.bar{height:8px;background:var(--red)}
.rule2{height:2px;background:var(--ink)}
.cols{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.pk-btn{font:700 13px/1 inherit;letter-spacing:.06em;text-transform:uppercase;
  background:var(--ink);color:var(--paper);border:2px solid var(--ink);border-radius:0;
  padding:12px 20px;cursor:pointer}
.pk-btn:hover{background:var(--paper);color:var(--ink)}
.pk-btn:focus-visible{outline:3px solid var(--red);outline-offset:2px}
.pk-btn.sec{background:var(--paper);color:var(--ink)}
.pk-btn.red{background:var(--red);border-color:var(--red);color:#fff}
.pk-btn[disabled]{background:var(--grey);border-color:var(--grey);cursor:not-allowed}
.f-hover{background:var(--paper)!important;color:var(--ink)!important}
.f-focus{outline:3px solid var(--red);outline-offset:2px}
.pk-field{width:100%;background:var(--paper);color:var(--ink);border:0;border-bottom:2px solid var(--ink);
  border-radius:0;padding:9px 0;font:400 15px/1.3 inherit;letter-spacing:.02em}
.pk-field:focus-visible{outline:3px solid var(--red);outline-offset:2px}
.pk-label{display:block;font-size:11px;letter-spacing:.06em;text-transform:uppercase;
  color:var(--grey);margin-bottom:6px}
.pk-err{margin-top:8px;font-size:12px;letter-spacing:.02em}
.pk-err .r{display:block;height:3px;background:var(--red);margin-bottom:6px;width:100%}
.pk-nav{display:flex;gap:22px;align-items:baseline;border-bottom:2px solid var(--ink);padding-bottom:10px}
.pk-nav a{color:var(--ink);text-decoration:none;font-size:12px;letter-spacing:.06em;
  text-transform:uppercase;display:inline-block;padding:6px 0;min-height:24px}
/* 12px uppercase with no padding renders 13.33px tall - under the 24x24 floor of
   WCAG 2.5.8. Swiss has no padding vocabulary, so this is a min-height, not a box. */
.pk-nav a[aria-current]{font-weight:700}
.pk-nav .sp{flex:1}
table.pk-t{width:100%;border-collapse:collapse;font-size:13px;letter-spacing:.02em}
table.pk-t th{text-align:left;font-size:11px;letter-spacing:.06em;text-transform:uppercase;
  color:var(--grey);font-weight:400;padding:0 8px 8px 0;border-bottom:2px solid var(--ink)}
table.pk-t td{padding:10px 8px 10px 0;border-bottom:1px solid var(--ink)}
.pk-scrim{background:rgba(0,0,0,.72);padding:36px 18px;display:flex;justify-content:center}
.pk-dialog{background:var(--paper);padding:24px;max-width:380px;width:100%}
.pk-empty{padding:28px 0;border-top:8px solid var(--red)}
.pk-skel{height:12px;background:#d4d4d4;margin-bottom:10px}
.swatch{border:0;height:54px}
